file.content:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --gold: #c8a96e;
  --gold-light: #dfc48e;
  --dark: #0c0c0c;
  --dark2: #141414;
  --dark3: #1e1e1e;
  --border: rgba(200,169,110,0.18);
  --text: #e2e2e2;
  --muted: #888;
  --r: 10px;
  --ease: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Noto Sans TC', 'PingFang TC', 'Microsoft JhengHei', sans-serif;
  background: var(--dark);
  color: var(--text);
  line-height: 1.75;
  font-size: 15px;
}

.container { max-width: 1140px; margin: 0 auto; padding: 0 24px; }
.gold { color: var(--gold); }
.center { text-align: center; }
.mt-40 { margin-top: 40px; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
section { padding: 100px 0; }

/* 標籤 */
.tag {
  font-size: 18px;
  letter-spacing: 3px;
  color: var(--gold);
  margin-bottom: 14px;
  font-weight: 600;
  display: block;
}

/* 區段標題 */
.section-title {
  font-family: 'Noto Serif TC', serif;
  font-size: clamp(26px, 3.5vw, 40px);
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 52px;
}

/* 按鈕 */
.btn-gold {
  display: inline-block;
  background: var(--gold);
  color: #0c0c0c;
  padding: 14px 32px;
  border-radius: 4px;
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 1px;
  transition: background var(--ease), transform var(--ease);
  cursor: pointer;
  border: none;
  font-family: inherit;
}
.btn-gold:hover { background: var(--gold-light); transform: translateY(-2px); }

.btn-line {
  display: inline-block;
  border: 2px solid var(--gold);
  color: var(--gold);
  padding: 12px 32px;
  border-radius: 4px;
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 1px;
  transition: all var(--ease);
}
.btn-line:hover { background: var(--gold); color: #0c0c0c; transform: translateY(-2px); }

.btn-outline {
  display: inline-block;
  border: 2px solid rgba(200,169,110,0.5);
  color: var(--gold);
  padding: 12px 32px;
  border-radius: 4px;
  font-weight: 700;
  font-size: 15px;
  transition: all var(--ease);
}
.btn-outline:hover { border-color: var(--gold); background: rgba(200,169,110,0.08); }

.hero-btns { display: flex; gap: 16px; flex-wrap: wrap; }

/* ===== NAVBAR ===== */
.navbar {
  position: fixed; top: 0; left: 0; right: 0;
  z-index: 1000;
  transition: background var(--ease), box-shadow var(--ease);
}
.navbar.scrolled {
  background: rgba(12,12,12,0.97);
  box-shadow: 0 2px 24px rgba(0,0,0,0.6);
}
.nav-inner {
  max-width: 1400px; margin: 0 auto; padding: 0 32px;
  display: flex; align-items: center;
  justify-content: space-between;
  height: 70px;
}
.logo { display: flex; flex-direction: column; line-height: 1.1; }
.logo-main {
  font-family: 'Noto Serif TC', serif;
  font-size: 26px; font-weight: 900;
  color: var(--gold); letter-spacing: 3px;
}
.logo-sub { font-size: 12px; letter-spacing: 3px; color: var(--muted); margin-top: 2px; }

