/* ===== 教練照片 ===== */
.coach-photo {
  margin: 0 auto 40px;
  border-radius: 16px;
  overflow: hidden;
  position: relative;
  box-shadow:
    0 0 0 2px var(--gold),
    0 0 0 6px var(--dark2),
    0 0 0 7px rgba(200,169,110,0.3),
    0 20px 60px rgba(0,0,0,0.6);
  transition: transform var(--ease);
}
.coach-photo img {
  width: 100%; display: block;
}
.coach-photo:hover { transform: translateY(-4px); }

/* Hero 用：圓角矩形垂直比例 */
.hero-photo {
  max-width: 280px;
  margin: 0 auto 36px;
}
.hero-photo img { aspect-ratio: 3/4; object-fit: cover; }

/* 章節用：標準橫向矩形 */
.chapter-photo {
  max-width: 540px;
  margin: 8px auto 44px;
}
.chapter-photo.portrait { max-width: 380px; }

.chapter-photo img { aspect-ratio: 3/4; object-fit: cover; }
.chapter-photo.landscape img { aspect-ratio: 16/10; }

.photo-caption {
  text-align: center;
  color: var(--muted);
  font-size: 13px;
  margin-top: -28px;
  margin-bottom: 36px;
  letter-spacing: 1.5px;
  font-style: italic;
}

