/* ===== 教練照片（左圖右文，bymyway 風格） ===== */
.coach-photo {
  position: relative;
  overflow: hidden;
  transition: transform var(--ease);
}
.coach-photo img {
  width: 100%; display: block;
  /* 邊緣淡出融進深底 */
  -webkit-mask-image: radial-gradient(ellipse at center, #000 55%, transparent 95%);
          mask-image: radial-gradient(ellipse at center, #000 55%, transparent 95%);
}
.coach-photo.solid img {
  -webkit-mask-image: none;
          mask-image: none;
  border-radius: 8px;
}

/* 章節雙欄布局：左圖右文 */
.chapter-grid {
  display: grid;
  grid-template-columns: minmax(280px, 1fr) 1.4fr;
  gap: 56px;
  align-items: center;
}
.chapter-grid.reverse {
  grid-template-columns: 1.4fr minmax(280px, 1fr);
}
.chapter-grid.reverse .coach-photo {
  order: 2;
}
.chapter-grid .coach-photo img {
  aspect-ratio: 3/4;
  object-fit: cover;
}
.chapter-grid .ch-body p:first-child {
  margin-top: 0;
}

/* Hero 區雙欄 */
.hero {
  text-align: left;
}
.hero-grid {
  display: grid;
  grid-template-columns: minmax(260px, 0.9fr) 1.3fr;
  gap: 60px;
  align-items: center;
  max-width: 1100px;
  width: 100%;
}
.hero-grid .coach-photo img { aspect-ratio: 3/4; object-fit: cover; }
.hero-grid .hero-quote { margin-left: 0; }

.photo-caption {
  color: var(--muted);
  font-size: 13px;
  margin-top: 14px;
  letter-spacing: 1.5px;
  font-style: italic;
  text-align: center;
}

/* 桌面寬版：章節 ch-num + ch-title 跟內文一起放右欄 */
@media (max-width: 900px) {
  .chapter-grid, .chapter-grid.reverse, .hero-grid {
    grid-template-columns: 1fr;
    gap: 32px;
    max-width: 540px;
    margin: 0 auto;
  }
  .chapter-grid.reverse .coach-photo { order: 0; }
  .hero { text-align: center; }
  .hero-grid .hero-quote { margin-left: auto; margin-right: auto; }
  .coach-photo { max-width: 360px; margin: 0 auto; }
}

