/* ===== NAVBAR ===== */
.navbar {
  position: fixed; top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(12,12,12,0.94);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.nav-inner {
  max-width: 1300px; margin: 0 auto;
  padding: 0 32px; height: 84px;
  display: flex; align-items: center; justify-content: space-between;
  gap: 32px;
}
.logo {
  display: flex; flex-direction: column;
  line-height: 1.05;
  flex-shrink: 0;
}
.logo-main {
  font-family: 'Noto Serif TC', serif;
  font-size: 36px; font-weight: 900;
  color: var(--gold);
  letter-spacing: 4px;
}
.logo-sub {
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 4px;
  margin-top: 4px;
  font-family: 'Noto Sans TC', sans-serif;
  font-weight: 400;
}

/* 5 張照片導覽 */
.nav-photos {
  display: flex; gap: 18px; align-items: center;
  flex: 1; justify-content: center;
}
.nav-photo {
  position: relative;
  display: block;
  width: 52px; height: 52px;
  border-radius: 50%;
  overflow: hidden;
  border: 2px solid var(--border);
  transition: all var(--ease);
  cursor: pointer;
}
.nav-photo img {
  width: 100%; height: 100%;
  object-fit: cover;
  display: block;
  -webkit-mask-image: none !important;
          mask-image: none !important;
}
.nav-photo:hover {
  border-color: var(--gold);
  transform: scale(1.12);
  box-shadow: 0 4px 16px rgba(200,169,110,0.4);
}
.nav-photo::after {
  content: attr(data-label);
  position: absolute;
  top: 60px; left: 50%;
  transform: translateX(-50%);
  background: var(--dark);
  color: var(--gold);
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 4px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--ease);
  border: 1px solid var(--border);
  font-family: 'Noto Sans TC', sans-serif;
  letter-spacing: 1px;
}
.nav-photo:hover::after { opacity: 1; }

.nav-back {
  font-size: 14px; color: var(--text-dim);
  border: 1px solid var(--border);
  padding: 8px 18px; border-radius: 4px;
  transition: all var(--ease);
  flex-shrink: 0;
  letter-spacing: 1px;
}
.nav-back:hover { border-color: var(--gold); color: var(--gold); }

/* navbar 占位，避免 fixed 蓋住 Hero */
body { padding-top: 84px; }

@media (max-width: 900px) {
  .nav-inner { height: 70px; padding: 0 18px; gap: 12px; }
  .logo-main { font-size: 26px; letter-spacing: 3px; }
  .logo-sub { font-size: 9px; letter-spacing: 3px; }
  .nav-photos { gap: 8px; }
  .nav-photo { width: 38px; height: 38px; }
  .nav-back { display: none; }
  body { padding-top: 70px; }
}

