/* ===== 核心思想（西洋棋比喻） ===== */
.coach-quote {
  background: var(--dark2);
  border-left: 4px solid var(--gold);
  border-radius: 0 12px 12px 0;
  padding: 40px 44px 32px;
  margin: 56px auto 0;
  max-width: 760px;
  position: relative;
  box-shadow: 0 20px 50px rgba(0,0,0,0.4);
}
.coach-quote::before {
  content: """;
  position: absolute;
  top: -28px; left: 28px;
  font-family: 'Noto Serif TC', serif;
  color: var(--gold);
  font-size: 90px;
  line-height: 1;
  opacity: 0.6;
  font-weight: 900;
}
.coach-quote p {
  font-family: 'Noto Serif TC', serif;
  font-size: 21px;
  line-height: 1.9;
  color: #fff;
  font-weight: 500;
}
.coach-quote footer {
  color: var(--gold);
  font-size: 12px;
  letter-spacing: 2.5px;
  margin-top: 24px;
  font-family: 'Noto Sans TC', sans-serif;
  padding-top: 16px;
  border-top: 1px dashed var(--border);
}

.chess-grid {
  margin: 56px auto 0;
  max-width: 880px;
  display: flex; flex-direction: column;
  gap: 14px;
}
.chess-row {
  display: grid;
  grid-template-columns: 1fr 70px 1fr;
  align-items: center;
  background: var(--dark2);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px 30px;
  transition: all var(--ease);
}
.chess-row:hover {
  border-color: var(--gold);
  transform: translateY(-2px);
}
.chess-row.highlight {
  background: linear-gradient(135deg, rgba(200,169,110,0.12), rgba(200,169,110,0.03));
  border-color: var(--gold);
  border-width: 2px;
}
.chess-left {
  font-family: 'Noto Serif TC', serif;
  color: var(--text-dim);
  font-size: 16px;
  font-weight: 500;
  line-height: 1.6;
  display: flex; align-items: center; gap: 14px;
}
.chess-icon {
  font-size: 28px;
  flex-shrink: 0;
}
.chess-arrow {
  color: var(--gold);
  font-size: 24px;
  text-align: center;
  font-weight: 700;
  font-family: 'Noto Serif TC', serif;
}
.chess-right {
  color: #fff;
  font-size: 17px;
  font-weight: 700;
  font-family: 'Noto Serif TC', serif;
  line-height: 1.6;
}
.chess-row.highlight .chess-right {
  color: var(--gold-light);
}

@media (max-width: 720px) {
  .coach-quote { padding: 32px 28px 24px; margin: 40px 0 0; }
  .coach-quote p { font-size: 17px; line-height: 1.75; }
  .chess-row {
    grid-template-columns: 1fr;
    gap: 12px; padding: 20px 22px;
    text-align: center;
  }
  .chess-left { justify-content: center; font-size: 15px; }
  .chess-arrow { font-size: 20px; }
  .chess-right { font-size: 15px; }
}

